10	}
11	
12	version = "${minecraft_version}-${mod_version}"
13	group = mod_group_id
14	
15	repositories {
16	    mavenCentral()
17	    maven {
18	        url = "https://www.cursemaven.com"
19	        content {
20	            includeGroup "curse.maven"
21	        }
22	    }
23	    maven {
