33	}
34	
35	java.toolchain.languageVersion = JavaLanguageVersion.of(25)
36	
37	neoForge {
38	    version = project.neo_version
39	
40	    runs {
41	        client {
42	            client()
43	            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
44	        }
45	
46	        server {
47	            server()
48	            programArgument '--nogui'
49	            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
50	        }
51	
52	        gameTestServer {
53	            type = "gameTestServer"
54	            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
55	        }
56	
57	        data {
58	            clientData()
59	            programArguments.addAll '--mod', project.mod_id, '--all', '--output', file('src/generated/resources/').getAbsolutePath(), '--existing', file('src/main/resources/').getAbsolutePath()
60	            systemProperty 'neoforge.enabledGameTestNamespaces', project.mod_id
61	        }
62	
63	        configureEach {
64	            systemProperty 'forge.logging.markers', 'REGISTRIES'
65	            logLevel = org.slf4j.event.Level.DEBUG
66	        }
67	    }
68	
69	    mods {
70	        "${mod_id}" {
71	            sourceSet(sourceSets.main)
72	        }
73	    }
74	}
75	
76	sourceSets.main.resources {
77	    srcDir 'src/generated/resources'
78	    exclude '.cache'
79	}
80	configurations {
81	    runtimeClasspath.extendsFrom localRuntime
82	}
83	
84	dependencies {
85	    implementation "curse.maven:agritech-evolved-1287394:9155589"
86	
87	    compileOnly "org.appliedenergistics:appliedenergistics2:${ae2_version}"
88	    compileOnly "curse.maven:applied-flux-965012:${appflux_file}"
89	    compileOnly "maven.modrinth:jade:26.1.12+neoforge"
90	    if (!project.hasProperty('noJade')) {
91	        localRuntime "maven.modrinth:jade:26.1.12+neoforge"
92	    }
93	    if (!project.hasProperty('noAe2')) {
94	        localRuntime "org.appliedenergistics:appliedenergistics2:${ae2_version}"
95	        localRuntime "org.appliedenergistics:guideme:${guideme_version}"
96	        if (!project.hasProperty('noAppliedFlux')) {
97	            localRuntime "curse.maven:applied-flux-965012:${appflux_file}"
98	            localRuntime "curse.maven:glodium-957920:${glodium_file}"
99	        }
100	    }
101	
102	    // Powah gives dev runs a fast FE source and FE cables. The mod has no code for it. Powah needs Cloth Config and GuideME.
103	    if (!project.hasProperty('noPowah')) {
104	        localRuntime "maven.modrinth:powah:7.0.4-alpha-neoforge"
105	        localRuntime "maven.modrinth:cloth-config:26.1.154+neoforge"
106	        localRuntime "org.appliedenergistics:guideme:${guideme_version}"
107	    }
108	
109	    // Oracle Index shows the guide book in dev runs. The mod has no code for it. Oracle Index needs Architectury.
110	    // z4LDmExp is the Modrinth maven id of the NeoForge 2.0.0 release, because the version number 2.0.0 also names the Fabric jar.
111	    if (!project.hasProperty('noOracleIndex')) {
112	        localRuntime "maven.modrinth:oracle-index:z4LDmExp"
113	        localRuntime "maven.modrinth:architectury-api:20.1.17+neoforge"
114	    }
115	
116	    // Logistics Networks lets dev runs check a node on the core. The mod has no code for it. This is the version ATM11 runs.
117	    if (!project.hasProperty('noLogisticsNetworks')) {
118	        localRuntime "curse.maven:logistics-networks-1448257:9115811"
119	    }
120	
121	    // Structure Lab takes screenshots for the project page. It is a local jar, so it loads only when a path is given.
122	    if (project.hasProperty('structureLabJar')) {
123	        localRuntime files(project.property('structureLabJar'))
124	    }
125	
126	    testImplementation platform("org.junit:junit-bom:5.13.4")
