128	    testImplementation "com.google.code.gson:gson:2.13.2"
129	    testRuntimeOnly "org.junit.platform:junit-platform-launcher"
130	}
131	
132	var generateModMetadata = tasks.register("generateModMetadata", ProcessResources) {
133	    var replaceProperties = [
134	            minecraft_version      : minecraft_version,
135	            minecraft_version_range: minecraft_version_range,
136	            neo_version            : neo_version,
137	            loader_version_range   : loader_version_range,
138	            mod_id                 : mod_id,
139	            mod_name               : mod_name,
140	            mod_license            : mod_license,
