147	}
148	sourceSets.main.resources.srcDir generateModMetadata
149	neoForge.ideSyncTask generateModMetadata
150	
151	tasks.named('test', Test) {
152	    useJUnitPlatform()
153	    // The release script and docs tests read these files from the repo instead of the classpath, so Gradle has to track them to rerun those tests after an edit.
154	    inputs.files('tools', '.github', 'docs/description.md', 'docs/media', 'README.md', 'CHANGELOG.md', 'CONTRIBUTING.md', 'DEVELOPMENT.md')
155	            .withPropertyName('repoFilesReadByTests')
156	            .withPathSensitivity(PathSensitivity.RELATIVE)
157	}
158	
159	tasks.named('processResources', ProcessResources) {
160	    from('wiki') {
161	        into 'assets/oracle_index/books/modular_planters'
162	    }
163	}
164	
165	var jarTask = tasks.named('jar', Jar) {
166	    exclude '**/gametest/**', '**/datagen/**', 'data/modular_planters/structure/empty.nbt'
167	    from('LICENSE.md', 'LICENSE-ATE.md')
168	}
169	
170	// The release workflow's checks build the jar once, and each publish job downloads that jar and passes it here with -PpublishJar, so every site gets the same jar instead of a rebuild.
171	def publishJar = providers.gradleProperty('publishJar')
172	
173	publishMods {
174	    file = publishJar.present ? layout.projectDirectory.file(publishJar.get()) : jarTask.flatMap { it.archiveFile }
175	    changelog = providers.exec {
176	        commandLine 'bash', file('tools/changelog-section.sh').path, project.version.toString(), file('CHANGELOG.md').path
177	    }.standardOutput.asText
178	    displayName = "${mod_name} ${project.version}"
179	    type = mod_version.contains('-alpha') ? ALPHA : mod_version.contains('-beta') ? BETA : STABLE
180	    modLoaders.add('neoforge')
181	    dryRun = providers.environmentVariable('DRY_RUN').present
182	
183	    github {
184	        accessToken = REDACTED
185	        repository = 'julian-perge/ModularPlanters'
186	        tagName = project.version.toString()
187	        displayName = project.version.toString()
188	        commitish = providers.environmentVariable('GITHUB_SHA').orElse('main')
189	    }
190	
191	    if (curseforge_project_id) {
192	        curseforge {
193	            accessToken = REDACTED
194	            projectId = curseforge_project_id
195	            minecraftVersions.add(minecraft_version)
196	            javaVersions.add(JavaVersion.VERSION_25)
197	            client = true
198	            server = true
199	            requires('agritech-evolved')
200	            optional('applied-energistics-2', 'applied-flux', 'jade', 'oracle-index', 'logistics-network')
201	        }
202	    }
203	
204	    // Logistics Networks is not on Modrinth, and Applied Flux's Modrinth slug is appflux.
205	    if (modrinth_project_id) {
206	        modrinth {
207	            accessToken = REDACTED
208	            projectId = modrinth_project_id
209	            minecraftVersions.add(minecraft_version)
210	            environment = CLIENT_AND_SERVER
211	            requires('agritech-evolved')
212	            optional('ae2', 'appflux', 'jade', 'oracle-index')
213	        }
214	    }
215	}
216	
217	tasks.withType(JavaCompile).configureEach {
218	    options.encoding = 'UTF-8'
219	    options.compilerArgs << '-Xlint:deprecation'
220	}
221	
222	idea {
223	    module {
224	        downloadSources = true
225	        downloadJavadoc = true
226	    }
227	}
